import os
# PYTHONPATH persists in REPL env and applies to later bash calls, but kernel already imported...
# Instead: append paths to sys.path now, and also export PYTHONPATH for future kernel restarts.
home = os.path.expanduser('~')
paths=[]
for name in ['attach-image','compact','edit','goal','refine','rlm-heartbeat']:
    src=f'/home/USER/.local/share/prime-agent/skills/{name}/src'
    if os.path.isdir(src): paths.append(src)
pp = ':'.join(paths)
os.environ['PYTHONPATH']=pp
import sys
for p in paths: sys.path.insert(0,p)
for m in ['attach_image','compact','edit','goal','refine','rlm_heartbeat']:
    try:
        __import__(m); print('OK', m)
    except Exception as e: print('FAIL', m, e)
# persist for future bash-spawned python / kernel restarts
try:
    with open(os.path.join(home,'.bashrc'),'a') as f: f.write(f'\nexport PYTHONPATH={pp}\n')
    print('bashrc updated')
except Exception as e: print('bashrc fail', e)
